        if (!r_list_append(globals, entry)) {
            free(entry);
            r_list_free(globals);
            return globals;
        }
    }

    return globals;
}

RList* get_global_entries_from_section(RBinWasmObj *bin, RBinWasmSection *sec) {
	if (!bin || !sec) {
		return NULL;
	}

	RList *globals = r_list_new();
	if (!globals) {
		return NULL;
	}

	size_t buf_len = sec->size;
	size_t offset = 0;

	while (offset < buf_len) {
		RBinWasmGlobal *entry = r_bin_wasm_global_new();
		if (!entry) {
			goto error;
		}

		// Parse content type
		if (offset >= buf_len) {
			goto error;
		}
		entry->content_type = bin->buffer[sec->offset + offset];
		offset++;

		// Parse mutability
		if (offset >= buf_len) {
			goto error;
		}
		entry->mutability = bin->buffer[sec->offset + offset];
		offset++;

		if (r_list_append(globals, entry) == -1) {
			goto error;
		}
	}

	return globals;

