#include <stdlib.h>

RList* get_global_entries(RBinWasmObj* bin, RBinWasmSection* sec) {
    RList* global_list = NULL;
    RBinWasmGlobal* global;
    ut8* buffer = sec->data;
    ut64 offset = 0;
    size_t buffer_len = sec->size;
    int limit = 1000;

    if (!(global_list = r_list_new())) {
        return NULL;
    }

    while (offset < buffer_len && limit-- > 0) {
        global = (RBinWasmGlobal*)malloc(sizeof(RBinWasmGlobal));
        if (!global) {
            r_list_free(global_list);
            return global_list;
        }

        // Read content type and mutability from the buffer
        global->type = buffer[offset];
        global->mutability = buffer[offset + 1];
        offset += 2;

        if (!r_list_append(global_list, global)) {
            free(global);
            r_list_free(global_list);
            return global_list;
        }
    }

    return global_list;
}
